package org.metaabm.examples.stupid5;

import org.eclipse.amp.escape.ascape.agf3d.GEF3DView;
import org.eclipse.amp.escape.ascape.adapt.Ascape3DPartFactory;
import org.eclipse.amp.agf3d.I3DModelFactoryProvider;
import org.eclipse.amp.escape.ascape.agf3d.GEF3DView;
import org.eclipse.swt.widgets.Display;
import org.eclipse.jface.viewers.IColorProvider;
import org.eclipse.gef.EditPartFactory;

/**
 * Stupid Model 5 Java Implementation.
 * 
 * Generated by metaabm system: Mar 26, 2010 10:30:54 PM PDT in project: org.eclipse.amp.amf.examples.escape  */
public class StupidModel53D extends StupidModel5
		implements
			I3DModelFactoryProvider {
	public void createGraphicViews() {
		addView(new GEF3DView());
	}

	public EditPartFactory getEditPart3DFactory() {
		return new Ascape3DPartFactory() {
			public IColorProvider getColorProvider(Object model) {

				if (model instanceof Bug) {
					return new org.metaabm.examples.stupid5.BugStyle2DColorProvider();
				}

				if (model instanceof Habitat) {
					return new org.metaabm.examples.stupid5.HabitatStyle2DColorProvider();
				}

				return null;
			}
		};
	}

}
